List<Integer> bfsNaDrzewie(TreeNode korzen) {
    List<Integer> wynik = new ArrayList<>();
    if (korzen == null) return wynik;
    Queue<TreeNode> kolejka = new ArrayDeque<>();
    kolejka.offer(korzen);
    while (!kolejka.isEmpty()) {
        TreeNode wezel = kolejka.poll(); // zdejmij z PRZODU
        wynik.add(wezel.wartosc);
        if (wezel.lewe != null) kolejka.offer(wezel.lewe);
        if (wezel.prawe != null) kolejka.offer(wezel.prawe);
    }
    return wynik;
}
// drzewo z lekcji 11 (8 jako korzen): wynik = [8, 3, 10, 1, 6, 14, 4, 7, 13]
// (poziom 0: 8 | poziom 1: 3,10 | poziom 2: 1,6,14 | poziom 3: 4,7,13)

int najkrotszaSciezka(Map<Integer, List<Integer>> graf, int start, int cel) {
    if (start == cel) return 0;
    Set<Integer> odwiedzone = new HashSet<>();
    Queue<Integer> kolejka = new ArrayDeque<>();
    odwiedzone.add(start);
    kolejka.offer(start);
    int odleglosc = 0;
    while (!kolejka.isEmpty()) {
        int rozmiarPoziomu = kolejka.size(); // ile wezlow na BIEZACYM poziomie
        odleglosc++;
        for (int i = 0; i < rozmiarPoziomu; i++) {
            int wezel = kolejka.poll();
            for (int sasiad : graf.getOrDefault(wezel, List.of())) {
                if (sasiad == cel) return odleglosc;
                if (odwiedzone.add(sasiad)) { // add() zwraca false, jesli juz bylo
                    kolejka.offer(sasiad);
                }
            }
        }
    }
    return -1; // cel nieosiagalny
}

// BLEDNIE: oznaczenie odwiedzenia PO zdjeciu z kolejki
Set<Integer> odwiedzone = new HashSet<>();
Queue<Integer> kolejka = new ArrayDeque<>();
kolejka.offer(start);
while (!kolejka.isEmpty()) {
    int wezel = kolejka.poll();
    if (odwiedzone.contains(wezel)) continue; // 'lataja' zbedne duplikaty w kolejce
    odwiedzone.add(wezel); // ZA POZNO - ten sam wezel mogl juz trafic do kolejki wielokrotnie
    for (int sasiad : graf.getOrDefault(wezel, List.of())) {
        kolejka.offer(sasiad); // brak sprawdzenia! kolejka puchnie duplikatami
    }
}

// POPRAWNIE: oznaczenie odwiedzenia PRZY DODANIU do kolejki
Set<Integer> odwiedzone = new HashSet<>();
Queue<Integer> kolejka = new ArrayDeque<>();
odwiedzone.add(start);
kolejka.offer(start);
while (!kolejka.isEmpty()) {
    int wezel = kolejka.poll();
    for (int sasiad : graf.getOrDefault(wezel, List.of())) {
        if (odwiedzone.add(sasiad)) { // add() zwraca true TYLKO przy pierwszym dodaniu
            kolejka.offer(sasiad); // gwarancja: kazdy wezel trafia do kolejki JEDEN raz
        }
    }
}

