int najkrotszaDrogaWSiatce(char[][] s) {
    int w = s.length, k = s[0].length;
    int[][] kier = {{1,0},{-1,0},{0,1},{0,-1}};
    boolean[][] odw = new boolean[w][k];
    Queue<int[]> q = new ArrayDeque<>();
    for (int i = 0; i < w; i++) for (int j = 0; j < k; j++)
        if (s[i][j] == 'S') { q.offer(new int[]{i, j}); odw[i][j] = true; }
    int kroki = 0;
    while (!q.isEmpty()) {
        int rozmiar = q.size();
        for (int n = 0; n < rozmiar; n++) {
            int[] p = q.poll();
            if (s[p[0]][p[1]] == 'E') return kroki;
            for (int[] d : kier) {
                int r = p[0] + d[0], c = p[1] + d[1];
                if (r < 0 || c < 0 || r >= w || c >= k) continue;
                if (odw[r][c] || s[r][c] == '#') continue;
                odw[r][c] = true;
                q.offer(new int[]{r, c});
            }
        }
        kroki++;
    }
    return -1;
}
// Czas i pamięć O(w * k) - każde pole trafia do kolejki najwyżej raz.

int[][] odlegloscOdNajblizszegoZera(int[][] m) {
    int w = m.length, k = m[0].length;
    int[][] wynik = new int[w][k];
    Queue<int[]> q = new ArrayDeque<>();
    for (int i = 0; i < w; i++) for (int j = 0; j < k; j++) {
        if (m[i][j] == 0) q.offer(new int[]{i, j});
        else wynik[i][j] = -1;
    }
    int[][] kier = {{1,0},{-1,0},{0,1},{0,-1}};
    while (!q.isEmpty()) {
        int[] p = q.poll();
        for (int[] d : kier) {
            int r = p[0] + d[0], c = p[1] + d[1];
            if (r < 0 || c < 0 || r >= w || c >= k || wynik[r][c] != -1) continue;
            wynik[r][c] = wynik[p[0]][p[1]] + 1;
            q.offer(new int[]{r, c});
        }
    }
    return wynik;
}
// O(w * k) zamiast O((w * k)^2) przy osobnym BFS dla każdej komórki.

