int odleglosc(Map<Integer, List<Integer>> graf, int start, int cel) {
    Map<Integer, Integer> dist = new HashMap<>();
    dist.put(start, 0);
    Queue<Integer> q = new ArrayDeque<>(List.of(start));
    while (!q.isEmpty()) {
        int w = q.poll();
        for (int s : graf.getOrDefault(w, List.of())) {
            if (!dist.containsKey(s)) { dist.put(s, dist.get(w) + 1); q.offer(s); }
        }
    }
    return dist.get(cel);
}
